import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { ACP_INTEGRITY, ACP_PACKAGE, ACP_RESOLUTION, ACP_VERSION, readAcpInputs, sha256 } from "./lib/acp-contract.mjs";

const root = process.cwd();
const mode = process.argv[2] ?? "--check";
if (!["--check", "--write"].includes(mode)) throw new Error("usage: node scripts/sync-acp-schemas.mjs --check|--write");
const inputs = await readAcpInputs(root);
const schemas = inputs.map((input) => ({
  id: input.id,
  stability: input.stability,
  packageSubpath: input.packageSubpath,
  path: input.repositoryPath,
  bytes: input.sourceBytes.length,
  sha256: sha256(input.sourceBytes),
}));
const manifest = {
  schemaVersion: "2.0",
  source: {
    package: ACP_PACKAGE,
    version: ACP_VERSION,
    lockfileVersion: "9.0",
    importer: ".",
    resolution: ACP_RESOLUTION,
    npmIntegrity: ACP_INTEGRITY,
  },
  java: { coordinate: "com.agentclientprotocol:acp-core:0.16.0" },
  schemas,
};
if (mode === "--write") {
  for (const input of inputs) {
    const destination = path.join(root, "protocol/acp", input.repositoryPath);
    await mkdir(path.dirname(destination), { recursive: true });
    await writeFile(destination, input.sourceBytes);
  }
  await writeFile(path.join(root, "protocol/acp/integrity.json"), `${JSON.stringify(manifest, null, 2)}\n`);
} else {
  for (const input of inputs) {
    if (!input.sourceBytes.equals(input.repositoryBytes)) throw new Error(`${input.repositoryPath} differs byte-for-byte from installed ACP SDK`);
  }
  const checkedIn = JSON.parse(await import("node:fs/promises").then(({ readFile }) => readFile(path.join(root, "protocol/acp/integrity.json"), "utf8")));
  if (JSON.stringify(checkedIn) !== JSON.stringify(manifest)) throw new Error("ACP integrity manifest is stale");
}
process.stdout.write(`ACP schemas ${mode === "--write" ? "synchronized from" : "match"} ${ACP_PACKAGE}@${ACP_VERSION}\n`);
